from sympy.core.add import Add
from sympy.core.expr import Expr
from sympy.core.singleton import S
from sympy.core.mul import Mul

def _eval_is_zero_new(self):
    if self.is_commutative is False:
        # issue 10528: there is no way to know if a nc symbol
        # is zero or not
        return

    # First check if any term is a complex number that can be simplified
    has_complex = False
    for a in self.args:
        if a.is_complex and not a.is_real and not a.is_imaginary:
            has_complex = True
            break

    # If we have complex terms, try to simplify first
    if has_complex:
        simplified = self.simplify()
        if simplified != self:
            return simplified.is_zero

    # Original logic for real and imaginary parts
    nz = []
    z = 0
    im_or_z = False
    im = False
    for a in self.args:
        if a.is_real:
            if a.is_zero:
                z += 1
            elif a.is_zero is False:
                nz.append(a)
            else:
                return
        elif a.is_imaginary:
            im = True
        elif (S.ImaginaryUnit*a).is_real:
            im_or_z = True
        else:
            return
    if z == len(self.args):
        return True
    if len(nz) == 0 or len(nz) == len(self.args):
        return None
    b = self.func(*nz)
    if b.is_zero:
        if not im_or_z and not im:
            return True
        if im and not im_or_z:
            return False
    if b.is_zero is False:
        return False

# Patch the Add class
Add._eval_is_zero = _eval_is_zero_new
